import sys

def main():
    flags = []
    filename = None

    i = 1
    while i < len(sys.argv):
        arg = sys.argv[i]
        if arg.startswith('-') and not arg.startswith('--'):
            for ch in arg[1:]:
                if ch in ('l', 'w', 'c'):
                    flags.append(ch)
                else:
                    print(f"Unknown flag: -{ch}", file=sys.stderr)
                    sys.exit(1)
        elif filename is None:
            filename = arg
        else:
            print("Unexpected argument", file=sys.stderr)
            sys.exit(1)
        i += 1

    if filename is None or filename == '-':
        data = sys.stdin.buffer.read()
    else:
        with open(filename, 'rb') as f:
            data = f.read()

    chars = len(data)
    lines = data.count(b'\n')
    # A final line with no trailing newline still counts as a line
    if data and not data.endswith(b'\n'):
        lines += 1
    words = len(data.split())

    show = flags if flags else ['l', 'w', 'c']

    values = {'l': lines, 'w': words, 'c': chars}
    output = [str(values[ch]) for ch in show]
    print(' '.join(output))

if __name__ == '__main__':
    main()
